solution.solution.cpp:
#include <string>
#include <string_view>

class TextBuilder
{
public:
    TextBuilder& add(std::string_view piece) { m_text += piece; return *this; }

    TextBuilder& repeat(char c, int times)
    {
        for (int i{ 0 }; i < times; ++i)
        {
            m_text += c;
        }
        return *this;
    }

    TextBuilder& line() { m_text += '\n'; return *this; }
    TextBuilder& clear() { m_text.clear(); return *this; }

    const std::string& text() const { return m_text; }
    std::size_t length() const { return m_text.length(); }

private:
    std::string m_text{};
};

unitTests:
TEST("chained building") { TextBuilder b{}; b.add("Total").add(": ").repeat('*', 3).line().add("done"); CHECK_EQ(b.text(), "Total: ***\ndone"); CHECK_EQ(b.length(), 15u); }
TEST("repeat with zero or negative") { TextBuilder b{}; b.repeat('x', 0).repeat('y', -3).add("ok"); CHECK_EQ(b.text(), "ok"); }
TEST("clear") { TextBuilder b{}; b.add("abc").clear().add("z"); CHECK_EQ(b.text(), "z"); }
TEST("text returns a reference, not a copy") { TextBuilder b{}; b.add("same"); CHECK(&b.text() == &b.text()); static_assert(std::is_same_v<decltype(std::declval<const TextBuilder&>().text()), const std::string&>); }

